using System.Data;using JamunaBank.Procurement.API.Data;using JamunaBank.Procurement.API.DTOs;using JamunaBank.Procurement.API.Models;using JamunaBank.Procurement.API.Repositories.Base;using JamunaBank.Procurement.API.Repositories.Interfaces;using Microsoft.Data.SqlClient;
namespace JamunaBank.Procurement.API.Repositories.Implementations;
public sealed class RequisitionMakerRepository(IStoredProcedureExecutor p):BaseRepository(p),IRequisitionMakerRepository
{
 public Task<StoredProcedureResult?> SaveAsync(long? id,SaveRequisitionRequest x,string emp,long org,CancellationToken ct){var(item,spec,opt)=Tables(x);return StoredProcedures.QuerySingleOrDefaultAsync("dbo.usp_Requisition_SaveMakerEditable",StoredProcedureResult.FromReader,[I("@RequisitionId",SqlDbType.BigInt,id),I("@RequestedByEmployeeId",SqlDbType.VarChar,emp,30),I("@RequestedOrgUnitId",SqlDbType.BigInt,org),I("@Justification",SqlDbType.NVarChar,x.Justification.Trim(),2000),Structured("@Items","dbo.RequisitionItemTableType",item),Structured("@SpecValues","dbo.RequisitionSpecValueTableType",spec),Structured("@SpecOptions","dbo.RequisitionSpecOptionTableType",opt),I("@Actor",SqlDbType.VarChar,emp,50)],ct);}
 public async Task<RequisitionDetailDto?> GetAsync(long id,string emp,CancellationToken ct){var ds=await StoredProcedures.QueryDataSetAsync("dbo.usp_Requisition_GetMakerDetail",[I("@RequisitionId",SqlDbType.BigInt,id),I("@RequesterEmployeeId",SqlDbType.VarChar,emp,30)],ct);if(ds.Tables[0].Rows.Count==0)return null;var h=ds.Tables[0].Rows[0];var specs=ds.Tables[2].AsEnumerable().GroupBy(r=>new{Item=r.Field<long>("REQ_ITEM_ID"),Id=r.Field<long>("ASSET_SPEC_ID"),Name=r.Field<string>("SPEC_NAME_SNAPSHOT")!,Type=r.Field<string>("SPEC_TYPE_SNAPSHOT")!,Text=r.Field<string?>("SPEC_TEXT_VALUE"),Num=r.Field<decimal?>("SPEC_NUM_VALUE"),Date=r.Field<DateTime?>("SPEC_DATE_VALUE"),Bool=r.Field<bool?>("SPEC_BOOL_VALUE")}).ToDictionary(g=>(g.Key.Item,g.Key.Id),g=>new RequisitionSpecificationValueDto(g.Key.Id,g.Key.Name,g.Key.Type,g.Key.Text,g.Key.Num,g.Key.Date is DateTime d?DateOnly.FromDateTime(d):null,g.Key.Bool,g.Where(r=>r.Field<long?>("ASSET_SPEC_OPTION_ID").HasValue).Select(r=>new SelectedSpecificationOptionDto(r.Field<long>("ASSET_SPEC_OPTION_ID"),r.Field<string>("SELECTED_OPTION_TEXT_SNAPSHOT")!)).ToArray()));var replacements=ds.Tables[3].AsEnumerable().ToDictionary(r=>r.Field<long>("REQ_ITEM_ID"),r=>new ReplacementInfoDto(r.Field<string?>("ASSET_TAG_NO"),r.Field<string?>("SERIAL_NO"),r.Field<string>("CURRENT_CONDITION")!,r.Field<string?>("ADDITIONAL_INFO")));var items=ds.Tables[1].AsEnumerable().Select(r=>{var iid=r.Field<long>("REQ_ITEM_ID");return new RequisitionItemDto(iid,r.Field<long>("ASSET_ID"),r.Field<string>("ITEM_NAME_SNAPSHOT")!,r.Field<string>("REQ_TYPE")!,r.Field<decimal>("QUANTITY"),r.Field<decimal>("ESTIMATED_UNIT_PRICE"),r.Field<string>("PURPOSE_JUSTIFICATION")!,r.Field<string?>("ADDITIONAL_SPEC_REQUIREMENT"),specs.Where(s=>s.Key.Item==iid).Select(s=>s.Value).ToArray(),replacements.GetValueOrDefault(iid));}).ToArray();var attachments=ds.Tables[4].AsEnumerable().Select(r=>new AttachmentDto(r.Field<long>("ATTACHMENT_ID"),r.Field<string>("ENTITY_TYPE")!,r.Field<long>("ENTITY_ID"),r.Field<string>("FILE_NAME")!,r.Field<string>("ORIGINAL_FILE_NAME")!,r.Field<string?>("FILE_EXTENSION"),r.Field<string?>("MIME_TYPE"),r.Field<long>("FILE_SIZE"),r.Field<string?>("DOCUMENT_TYPE"),r.Field<DateTime>("UPLOADED_DATE"))).ToArray();return new(h.Field<long>("REQUISITION_ID"),h.Field<string>("REQUISITION_NO")!,h.Field<string>("REQUESTED_BY_EMPLOYEE_ID")!,h.Field<long>("REQUESTED_ORG_UNIT_ID"),h.Field<string>("ORG_UNIT_NAME")!,h.Field<DateTime>("REQUESTED_DATE"),h.Field<string>("JUSTIFICATION")!,h.Field<decimal>("TOTAL_ESTIMATED_AMOUNT"),h.Field<string>("CURRENT_STATUS")!,items,attachments,h.Field<string?>("PENDING_STAGE"),h.Field<string?>("PENDING_WITH_EMPLOYEE_ID"),h.Field<string?>("PENDING_WITH_NAME"),h.Field<string?>("PENDING_WITH_LABEL"));}
 public Task<IReadOnlyList<RequisitionSummaryDto>> GetMineAsync(string emp,CancellationToken ct)=>StoredProcedures.QueryAsync("dbo.usp_Requisition_GetMine",r=>new RequisitionSummaryDto(r.GetInt64(r.GetOrdinal("REQUISITION_ID")),r.GetString(r.GetOrdinal("REQUISITION_NO")),r.GetDateTime(r.GetOrdinal("REQUESTED_DATE")),r.GetString(r.GetOrdinal("JUSTIFICATION")),r.GetDecimal(r.GetOrdinal("TOTAL_ESTIMATED_AMOUNT")),r.GetString(r.GetOrdinal("CURRENT_STATUS")),r.GetInt32(r.GetOrdinal("ITEM_COUNT"))),[I("@RequesterEmployeeId",SqlDbType.VarChar,emp,30)],ct);
 public Task<StoredProcedureResult?> SubmitAsync(long id,string emp,string? remarks,CancellationToken ct)=>StoredProcedures.QuerySingleOrDefaultAsync("dbo.usp_Requisition_SubmitValidated",StoredProcedureResult.FromReader,[I("@RequisitionId",SqlDbType.BigInt,id),I("@ActorEmployeeId",SqlDbType.VarChar,emp,30),I("@Remarks",SqlDbType.NVarChar,remarks,2000)],ct);
 private static (DataTable,DataTable,DataTable) Tables(SaveRequisitionRequest x){var i=T(("CLIENT_ITEM_KEY",typeof(int)),("ASSET_ID",typeof(long)),("REQ_TYPE",typeof(string)),("QUANTITY",typeof(decimal)),("ESTIMATED_UNIT_PRICE",typeof(decimal)),("PURPOSE_JUSTIFICATION",typeof(string)),("ADDITIONAL_SPEC_REQUIREMENT",typeof(string)),("ASSET_TAG_NO",typeof(string)),("SERIAL_NO",typeof(string)),("CURRENT_CONDITION",typeof(string)),("REPLACEMENT_ADDITIONAL_INFO",typeof(string)));var s=T(("CLIENT_ITEM_KEY",typeof(int)),("ASSET_SPEC_ID",typeof(long)),("SPEC_TEXT_VALUE",typeof(string)),("SPEC_NUM_VALUE",typeof(decimal)),("SPEC_DATE_VALUE",typeof(DateTime)),("SPEC_BOOL_VALUE",typeof(bool)));var o=T(("CLIENT_ITEM_KEY",typeof(int)),("ASSET_SPEC_ID",typeof(long)),("ASSET_SPEC_OPTION_ID",typeof(long)));for(var n=0;n<x.Items.Count;n++){var q=x.Items[n];i.Rows.Add(n,q.AssetId,q.RequisitionType.Trim().ToUpperInvariant(),q.Quantity,q.EstimatedUnitPrice,q.PurposeJustification,q.AdditionalSpecificationRequirement,q.ReplacementInfo?.AssetTag,q.ReplacementInfo?.Serial,q.ReplacementInfo?.CurrentCondition,q.ReplacementInfo?.AdditionalInfo);foreach(var v in q.DynamicSpecifications){s.Rows.Add(n,v.SpecId,v.TextValue,v.NumberValue,v.DateValue?.ToDateTime(TimeOnly.MinValue),v.BoolValue);foreach(var option in v.OptionIds.Distinct())o.Rows.Add(n,v.SpecId,option);}}return(i,s,o);}
 private static DataTable T(params(string,Type)[] cs){var t=new DataTable();foreach(var(n,x)in cs)t.Columns.Add(n,x);return t;}private static SqlParameter Structured(string n,string type,DataTable value)=>new(n,SqlDbType.Structured){TypeName=type,Value=value};private static SqlParameter I(string n,SqlDbType t,object? v,int? s=null)=>SqlParameterFactory.Input(n,t,v,s);
}
